import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const home=readFileSync('src/pages/index.astro','utf8');
const vote=readFileSync('src/pages/vote/index.astro','utf8');
const admin=readFileSync('src/pages/vote/manage/index.astro','utf8');
const reviews=readFileSync('src/pages/reviews/index.astro','utf8');
const reviewApp=readFileSync('apps-script/Code.js','utf8');
const contact=readFileSync('src/components/ContactSheet.astro','utf8');
const scriptWorkflow=readFileSync('.github/workflows/deploy-apps-script.yml','utf8');
const siteWorkflow=readFileSync('.github/workflows/deploy.yml','utf8');

const reviewData=readFileSync('src/data/reviews.ts','utf8');
const grants=readFileSync('supabase/migrations/20261122150000_singer_vote_service_role_grants.sql','utf8');
const backend=readFileSync('supabase/functions/singer-vote/index.ts','utf8');
const sql=readFileSync('supabase/migrations/20261122140000_singer_finale_voting.sql','utf8');
assert.ok(home.includes('id="live-voting-link"'), 'Voting shortcut must be present');
assert.ok(!home.includes('id="live-voting-link" style="display:none"'), 'Catalogue link must not be hidden between events');
assert.ok(home.includes('<a href="/reviews/">Отзывы</a>'), 'Reviews must be in main navigation');
assert.ok(home.includes('class="quick-card" href="/reviews/"'), 'Reviews must be beside repertoire and afisha shortcuts');
assert.ok(!home.includes('aria-label="Посмотреть тестовую страницу отзывов"'), 'Remove duplicate guest-section reviews link');
assert.ok(home.includes('data-voting-visibility'), 'Homepage must check server poll status');
assert.ok(vote.includes('Голосование пока закрыто'), 'Closed state missing');
assert.ok(vote.includes('1 000 ₽'), 'Paid ordering information missing');
assert.ok(vote.includes('song_ids:choices'), 'Selected 1–3 songs must be submitted');
assert.ok(vote.includes('n<1||n>3'), 'Allow 1–3 songs and reject empty selection');
assert.ok(backend.includes('return json({active:false,test_mode:false,songs:'), 'Inactive polls must return preview catalogue');
assert.ok(vote.includes("const incoming=Array.isArray(result.songs)?result.songs:[]"), 'Closed catalogue must still populate song list');
assert.ok(vote.includes("n<1||n>3||songs.length<1||!active"), 'Ballot requires at least one song and an active session');
assert.ok(backend.includes('enabled:true'), 'Explicit admin activation missing');
assert.ok(backend.includes('singer_vote_admin'), 'Admin authentication missing');
assert.ok(backend.includes('playlist_variants'), 'Eligible songs must come from existing catalogue');
assert.ok(backend.includes('filename.includes("@")'), 'Filename eligibility marker missing');
assert.ok(backend.includes('ensureCalendarSessions(db)'), 'Public calendar windows should auto-open polls');
assert.ok(backend.includes('originalEnd-3600000'), 'Voting must close 1 hour after performance, not 2');
assert.ok(!vote.includes('id="vote-admin"'), 'Admin controls must not be present on the public guest page');
assert.ok(admin.includes('id="vm-key"'), 'Dedicated password-protected admin page missing');
assert.ok(admin.includes('noindex,nofollow'), 'Admin page should not be indexed');
assert.ok(admin.includes('setInterval(()=>refreshStatus(true),5000)'), 'Owner results must refresh every 5s');
assert.ok(vote.includes('vote-count'), 'Guest results must display votes per song');
assert.ok(vote.includes('setInterval(refresh,18000)') && vote.includes('setInterval(checkStatus,6000)'), 'Separate fast status updates from full vote tallies');
assert.ok(vote.includes('checkStatus();') && vote.includes("endpoint+'?status=1'"), 'Fast vote status endpoint must load immediately');
assert.ok(vote.includes('statusKnown') && vote.includes('Проверяем голосование…'), 'Unknown vote status must not masquerade as closed');
assert.ok(backend.includes('searchParams.get("status")==="1"') && backend.includes('scheduleSyncStartedAt'), 'Server must serve fast status without waiting for catalogue or repeated Google fetches');
assert.ok(backend.includes('getTally(db,data.id)'), 'Public API must return aggregated vote tallies');
assert.ok(grants.includes('grant select, insert, update, delete on public.singer_vote_sessions to service_role'), 'Missing required voting table permission fix');
assert.ok(!grants.includes('to anon'), 'Vote tables must not be granted to anonymous clients');
assert.ok(home.includes('href="/reviews/"'), 'Reviews page must be linked from home');
assert.ok(reviews.includes('class="btn primary js-contact-sheet"'), 'Review button must use shared popup');
assert.ok(reviews.includes('<ContactSheet />'), 'Reviews must use canonical popup component');
assert.ok(home.includes('<ContactSheet />'), 'Homepage must use same popup component');
assert.ok(contact.includes('data-messenger="max"') && contact.includes('data-messenger="telegram"') && contact.includes('data-messenger="whatsapp"'), 'Popup must have MAX Telegram WhatsApp');
assert.ok(!reviews.includes('review-actions">\n   <a'), 'No duplicated messenger buttons in review CTA');
assert.ok(!reviews.includes('reviews-demo'), 'Public reviews page must not show demo testimonials');
assert.ok(reviewData.includes('demo: true'), 'Demo review must never masquerade as a customer testimonial');
assert.ok(backend.includes('singer_cast_vote'), 'Atomic ballot submission missing');
assert.ok(backend.includes('ids.length<1||ids.length>3||new Set(ids).size!==ids.length'), 'Server must accept 1–3 distinct songs');
const oneToThree=readFileSync('supabase/migrations/20261122180000_singer_vote_one_to_three.sql','utf8');
assert.ok(oneToThree.includes('cardinality(p_song_ids) not between 1 and 3'), 'Database must accept 1–3 songs');
assert.ok(oneToThree.includes('do update set song_ids = excluded.song_ids'), 'Re-voting must replace rather than accumulate the ballot');
assert.ok(sql.includes('enabled boolean not null default false'), 'Database default must remain closed');
assert.ok(sql.includes('primary key (session_id, voter_hash)'), 'One ballot per guest must be enforced');
assert.ok(sql.includes('enable row level security'), 'RLS missing');

assert.ok(vote.includes('<style is:global>'), 'Dynamically generated voting rows must receive CSS styles');
assert.ok(vote.includes('vote-preview') && vote.includes('vote-player'), 'Voting should use inline song previews');
assert.ok(vote.includes("const name=document.createElement('strong');"), 'Track title must be a local DOM node, not window.name');
assert.ok(!vote.includes("info.className='vote-songtext',name="), 'Malformed comma declaration must never reappear');
assert.ok(vote.includes('PAUSE_ICON') && vote.includes('PLAY_ICON'), 'Use vector playback icons');
assert.ok(vote.includes('votes.hidden=!state?.active'), 'Hide vote-count placeholders outside event');
assert.ok(backend.includes('preview_url'), 'Voting API should return public safe audio previews');
assert.ok(reviewApp.includes('function publicReviews_()'), 'Reviews must come from the existing photo/video Sheet');
assert.ok(reviewApp.includes("e.parameter.kind === 'vote-config'"), 'Sheet must expose safe manual voting schedule');
assert.ok(reviewApp.includes('function publicVotingSchedule_()'), 'Sheet voting config must be validated');
assert.ok(backend.includes('ensureManualSheetSession(db)'), 'Polls must open from Google Sheet controls');
assert.ok(backend.includes('source_key:source'), 'Each sheet event must get a distinct voting session');
assert.ok(reviewApp.includes('row[6]===true&&safe(row[0])&&safe(row[4])'), 'Only owner-approved testimonials may be published');
assert.ok(reviewApp.includes("e.parameter.kind === 'reviews'"), 'Approved reviews endpoint must exist');
assert.ok(reviews.includes('singerReviewsLoaded'), 'Review page must consume Sheet data');
assert.ok(reviews.includes("avatarType==='female'"), 'Customisable gender avatar defaults required');
assert.ok(siteWorkflow.includes('**/reviews/uploads/**'), 'FTP deployment must protect user-uploaded avatars');
assert.ok(scriptWorkflow.includes('clasp deploy --deploymentId'), 'Apps Script web app needs versioned redeploy to update production endpoint');
assert.ok(backend.includes('EdgeRuntime.waitUntil(sync.then') && backend.includes('ensureCalendarSessions(db),ensureManualSheetSession(db)'), 'Calendar, Sheet and repertoire must all load concurrently');
assert.ok(vote.includes('CATALOGUE_CACHE_KEY'), 'Voting must show fast cached repertoire');
assert.ok(vote.includes("fetch('/data/repertoire.public.json'"), 'Static catalogue should work even during voting API outages');
assert.ok(vote.includes('vote-progress-fill'), 'Each active song must display its voting progress');
assert.ok(home.includes('class="section home-reviews"') && home.includes('home-reviews-track'), 'Homepage must have swipable reviews carousel');
assert.ok(home.includes('if(!reviews.length){track.replaceChildren();section.hidden=true;return;}') && home.includes('section.hidden=false;requestAnimationFrame(controls)'), 'Only show homepage reviews after approved reviews load');
assert.ok(!home.includes('Не настоящий отзыв') && !home.includes('Пример оформления'), 'Public homepage must not show demo reviews');
assert.ok(contact.includes('whatsapp://send?phone='), 'Mobile WhatsApp deep link missing');
const testMigration=readFileSync('supabase/migrations/20261122190000_singer_vote_test_mode.sql','utf8');
assert.ok(testMigration.includes('test_mode boolean not null default false'), 'Existing real sessions must stay normal by default');
assert.ok(backend.includes('voteSession.test_mode?":"+(requestId||crypto.randomUUID()):""'), 'Only test submissions may count repeatedly, with stable retry IDs');
assert.ok(backend.includes('runId==="legacy"'), 'Legacy live votes must be preserved on initial transition');
assert.ok(vote.includes("singer-vote-choice:") && vote.includes('localStorage.setItem'), 'Normal voters should be able to add to and revise their earlier choice');
assert.ok(vote.includes('Отправить пробный голос') && vote.includes('vote-test-note'), 'Public page should clearly disclose test voting');
assert.ok(reviewApp.includes("sheet.getRange('B8').getValue()===true"), 'Test mode must be controlled by the existing Sheet');
assert.ok(reviewApp.includes('SINGER_VOTE_SHEET_RUN_ID'), 'Switching vote modes must create independent sessions');
assert.ok(!reviewApp.includes("row[6]===true&&row[9]===true"), 'Removed consent checkbox must not block approved reviews');
assert.ok(home.includes('aria-label="Отзывы гостей" hidden'), 'Homepage reviews stay hidden until approved reviews arrive');
const cacheWorkflow=readFileSync('.github/workflows/sync-reviews.yml','utf8');
const cacheSync=readFileSync('.github/scripts/sync-reviews.py','utf8');
assert.ok(home.includes("fetch('/data/reviews.json'") && reviews.includes("fetch('/data/reviews.json'"), 'Both pages must use the fast same-origin reviews snapshot');
assert.ok(!home.includes('exec?kind=reviews&callback=') && !reviews.includes('exec?kind=reviews&callback='), 'Visitors must not wait for Google Apps Script');
assert.ok(home.includes('singer-public-reviews-v1') && reviews.includes('singer-public-reviews-v1'), 'Review pages must render a recent local snapshot immediately');
assert.ok(cacheWorkflow.includes('workflow_dispatch:') && !cacheWorkflow.includes('cron:') && !cacheWorkflow.includes('  schedule:') && !cacheWorkflow.includes('  push:'), 'Reviews must refresh only when explicitly requested');
assert.ok(cacheSync.includes('ftp.rename("reviews.json.tmp", "reviews.json")'), 'Public reviews must publish atomically without an empty-state window');
assert.ok(siteWorkflow.includes('**/data/reviews.json'), 'Main site deploy must preserve the independently updated review cache');

assert.ok(home.includes('home-reviews-carousel') && home.includes('id="reviews-controls" hidden'), 'Carousel arrows must overlay cards only when scrolling is possible');
assert.ok(vote.includes('vote-choice-hint') && vote.includes('Отправить голос'), 'Voting must have floating CTA and selection guidance');
assert.ok(vote.includes('vote-player button svg{display:block;flex:none}'), 'Player SVGs should be centered in circular buttons');
assert.ok(vote.includes("'Изменить голос'") && vote.includes("'Сохранить изменения'"), 'Voters should be able to revise their ballot');
assert.ok(vote.includes('STATUS_CACHE_KEY') && vote.includes('refreshBusy'), 'Voting should reuse recent state and avoid duplicate requests');
assert.ok(vote.includes('checkStatus().finally(()=>{if(!document.hidden)refresh()})'), 'Fast vote status should complete before full tally fetch');
assert.ok(!vote.includes('checkStatus();\n refresh();'), 'Avoid competing initial requests to the same Edge Function');
assert.ok(vote.includes('testSubmissions++'), 'Test submissions should provide immediate feedback');
assert.ok(vote.includes('PENDING_VOTE_KEY') && vote.includes('request_id:crypto.randomUUID()'), 'Failed votes must keep a durable request ID');
assert.ok(vote.includes("$('vote-actions').hidden=n===0&&!pendingVote"), 'Pending vote must remain visible after reload');
assert.ok(vote.includes('if(pendingVote){await sendPendingVote();return}'), 'Manual retries must reuse pending request');
assert.ok(vote.includes("key?'application/json':'text/plain;charset=UTF-8'"), 'Guest vote POST must avoid unnecessary CORS preflight');
assert.ok(backend.includes('const [sessionResult,eligibleSongs]=await Promise.all(['), 'Server vote validation lookups must be concurrent');
assert.ok(vote.includes("$('vote-actions').hidden=n===0") && !vote.includes("$('vote-actions').hidden=!active||n===0"), 'Selected songs must reveal the CTA even if poll is closed');
assert.ok(vote.indexOf('id="vote-actions"')>vote.indexOf('</main>'), 'Fixed CTA must not be clipped by vote card overflow');
assert.ok(vote.includes('voteLabel(song,total)') && vote.includes("if(!votes)return ''"), 'Zero votes must not display percentages');
console.log('Finale voting, isolated test mode, editable ballots and reviews carousel checks passed.');

